// Ramura „Medical”: pregătește emailul (destinatari = lista de distribuție a tipului de ședință)
const ROUTE = 'medical';
return $input.all().map((item) => {
  const b = item.json.body;
  const binary = {};
  (b.attachments || []).forEach((a, i) => {
    binary['att' + i] = {
      data: a.content_b64,
      fileName: a.filename,
      mimeType: a.filename.endsWith('.docx')
        ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
        : 'application/octet-stream',
    };
  });
  return {
    json: {
      route: ROUTE, priority: 'high', job_id: b.job_id,
      to: (b.recipients || []).join(', '), from: b.sender,
      subject: b.subject, html: b.html,
      attachments: Object.keys(binary).join(','),
    },
    binary,
  };
});

